"按 Q 施展专属门派武学。青锋的「疾风斩」附带位移穿透与破防。": "Q로 전용 유파 무공을 사용하세요. 청봉의 「질풍참」은 이동 관통과 가드 파괴가 붙습니다.",
"按 W 或空格起跳，身在半空再按一次，便是二段跳。": "W 또는 스페이스로 점프하고, 공중에서 한 번 더 누르면 2단 점프가 됩니다.",
