"按住左键再点右键（或直接按 R）。各派武学各异，青锋可挥出疾速剑气。": "좌클릭을 누른 채 우클릭(또는 R 키). 유파마다 무공이 다르며 청봉은 빠른 검기를 날립니다.",
"按住左键蓄力，待寒芒一闪、剑鸣铮铮时松手。蓄满的一斩为霸体不可挡，能强行破防！": "좌클릭을 누른 채 차지하다가 한광이 번쩍이고 검명이 울릴 때 놓으세요. 가득 찬 일격은 슈퍼 아머라 막을 수 없고 가드를 강제로 깨뜨립니다!",
"挑击": "올려치기",
"挑选本命侠客登临万仞剑阁，突破层层守关者，顿悟三选一武林秘卷！": "본명 협객을 골라 만인 검각에 올라 층마다 문지기를 돌파하고, 깨달음으로 무림 비권 세 개 중 하나를 얻으세요!",
