"极简沉浸：仅保留气血与真气条": "극간 몰입: 체력과 내공 바만 유지합니다",
"标准三局两胜（BO3）1v1 对决。先在上方选好电脑境界与战场规则（常规标准已融合动态天机异变），点击「进入选人 · 开战」即可开打；也可观战 AI 对决或开启新手教学。": "표준 3판 2승(BO3) 1대1 대결입니다. 위에서 컴퓨터 경지와 전장 규칙(일반 표준에는 동적 천기 이변이 합쳐져 있음)을 고른 뒤 ‘선택 화면 진입 · 개전’을 누르면 시작합니다. AI 대결을 관전하거나 신규 튜토리얼도 시작할 수 있습니다.",
"核心门派技能": "핵심 유파 기술",
"检测到作弊": "부정행위가 감지되었습니다",
