"清鸣振翼展开翠岚灵域，净化自身与五层范围内队友异常并回复气血，同时向四周散射十二道贯穿追踪翠羽箭刃。": "맑은 울음과 함께 날개를 떨쳐 취람 영역을 펼치고, 자신과 5층 범위 안 동료의 이상 상태를 정화하며 체력을 회복합니다. 동시에 사방으로 관통 추적 취우 화살 열두 줄기를 흩뿌립니다.",
