" · 登录云端账号才能领星座皮肤": " · 클라우드 계정으로 로그인해야 황도 스킨을 받을 수 있습니다",
" · 行动中": " · 행동 중",
"去所属套装": "소속 세트로 이동",
"卸下": "벗기",
"暂无已解锁徽记，可点击顶部「领紫金豪礼」或前往武库解锁。": "해금된 휘장이 없습니다. 상단 ‘자금 호화 선물 수령’을 누르거나 무기고에서 해금하세요.",
"版本": "버전",
"仅存斩数版": "처치 카운터판 전용",
"（无普通版本）": "(일반판 없음)",
"或": "또는",
"调": "조절",
"限免活动只包括游戏里原有的皮肤，活动结束就收回。从武库拿到的饰品永久拥有，能在市场卖掉，开出斩数版还会记击倒数。": "한정 무료 이벤트는 게임에 원래 있던 스킨만 포함하며 이벤트가 끝나면 회수됩니다. 무기고에서 얻은 장신구는 영구 보유하고 장터에서 팔 수 있으며, 처치 카운터판이 나오면 처치 수도 기록됩니다.",
"斩数版：穿着它每击倒一个对手，计数 +1": "처치 카운터판: 착용하고 상대를 쓰러뜨릴 때마다 카운트 +1",
"当前侠客未装配徽记。前往「英雄」或「武库 → 徽记」即可一键装配并在训练场实时验证触发效果。": "현재 협객에게 장착된 휘장이 없습니다. ‘협객’ 또는 ‘무기고 → 휘장’에서 한 번에 장착하고 훈련장에서 발동 효과를 실시간으로 확인하세요.",
"当前未携带灵宠。可在「武库 → 灵宠」收养并携宠出战，在训练场按 V 键实时观测效果。": "현재 펫이 없습니다. ‘무기고 → 펫’에서 입양해 함께 출전하고, 훈련장에서 V 키로 효과를 실시간 관찰하세요.",
"该分类暂无已解锁徽记": "이 분류에 해금된 휘장이 없습니다",
"穿着": "착용 중",
"新": "신",
"V 键就绪": "V 키 준비 완료",
"★ 天工传世 · 仅存斩数版": "★ 천공 가보 · 처치 카운터판 전용",
"《天工传世 · 器灵纪》至臻典藏，仅存斩数版，穿戴即解锁实战攻守双境。仅可由天工传世匣或玩家市场取得，货郎与熔铸契不产出。": "《천공 가보 · 기령기》 지고의 컬렉션이며 처치 카운터판만 존재합니다. 착용하면 실전 공수 쌍경이 해금됩니다. 천공 가보 상자나 플레이어 장터로만 얻을 수 있고 행상과 주조 계약에서는 나오지 않습니다.",
"不装备": "장착 안 함",
"不要（这台货郎就没了）": "받지 않기 (이 행상이 사라집니다)",
"与大招": "과 대초식",
"主动 V": "액티브 V",
"今天第一笔": "오늘 첫 거래",
"仙阶圆满": "선급 원만",
"你赢了": "승리했습니다",
"你输了": "패배했습니다",
"养成优先": "육성 우선",
"凯旋大捷！": "개선 대승!",
"单机": "싱글",
"友": "친구",
"可拖动标题栏移动面板 · 拖动队友至分工或敌方目标": "제목 표시줄을 끌어 패널을 옮길 수 있습니다 · 동료를 끌어 역할 분담이나 적 대상에 지정하세요",
"名 AI 队友": "명 AI 동료",
"否": "아니요",
"品质最低": "낮은 등급 순",
"品阶优先": "등급 우선",
"回滚中": "롤백 중",
"在卖的多": "판매 많은 순",
"在设置里打开「纯键盘模式」，选中框会一直亮着，对局里鼠标不出招。": "설정에서 ‘키보드 전용 모드’를 켜면 선택 틀이 항상 켜져 있고 대전에서 마우스로 기술을 쓰지 않습니다.",
"守城战": "수성전",
"完整教学": "전체 튜토리얼",
"定级完成": "배치 완료",
"对方 ": "상대 ",
"封": "봉",
"小队协同": "소대 협동",
"已佩戴": "착용 중",
"已收养": "입양함",
"已领": "수령함",
"开发组补偿": "개발팀 보상",
"当前队伍暂无 AI 队友": "현재 팀에 AI 동료가 없습니다",
"循环 · 负极能一直连": "순환 · 음극으로 계속 연결 가능",
"惜败，择日再战！": "아쉽게 패했습니다. 훗날 다시 겨루죠!",
"成交最多": "거래 많은 순",
"战队战术": "팀 전술",
"折戟": "절극",
"拖拽至分工或敌方目标": "끌어서 역할 분담 또는 적 대상에 지정",
"挂着": "등록 중",
"指挥": "지휘",
"按名称": "이름별",
"按名称排序": "이름순",
"按套装": "세트별",
"按类别": "분류별",
"控制 AI 队友站位与聚散": "AI 동료의 위치와 집결·분산을 제어합니다",
"收养": "입양",
